    { id = "ps-teld-122", ["do"] = "accept", quest = 490, npc = 2155, at = {1438, 42.22, 51.27}, text = "Sigue al oeste y coge la recompensa de la Centinela Shayla Nightbreeze.", tip = "Al oeste por el camino hacia la ciudad. Shayla recorre este tramo del camino, desde la flecha al suroeste hasta la curva en torno a 38,54, y vuelta: si no está en la flecha, sigue el camino al suroeste. Todos los fúrbolg Tuercepinos sueltan colmillos: cuentan los emboscadores de este camino, los del túmulo y los de Gnarlpine Hold.", status = "unverified", reqlevel = 5 },
